vec2 uv_m = 1.0 - abs( fract( uv * 0.5 ) * 2.0 - 1.0 ); // Eo.S' mirror code
ret.x = texture( sampler_fc_main, uv_m ).x*0.5;
vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * 1.2 + rand_frame.xy;
vec2 uv_mid = uv_orig +(texture(sampler_noise_lq, dither_uv).xyz-0.5)*(vec2(1.0)/uTexSize) * 1.0;
ret.y = GetPixel(uv_mid).y - 0.008;
}

